    "explanation": "The partition coefficient (log P) measures how a drug distributes between a lipid phase (commonly octanol) and water, indicating lipophilicity. It influences membrane permeability, absorption and distribution. The distribution coefficient (log D) accounts for ionisation at a given pH.",
    "rationales": {
      "oep-ke-keph-pharmacy-077-option-0": "Renal excretion rate is a clearance concept, not log P.",
      "oep-ke-keph-pharmacy-077-option-2": "Melting temperature is a separate physical property.",
      "oep-ke-keph-pharmacy-077-option-3": "log P itself refers to lipophilicity; ionisation at a given pH is captured by log D."
    },
