    "id": "ppl-kenya-ppb-s1p1-015",
    "objective": "ppl-kenya-ppb-s1p1-015",
    "course": "paper-1",
    "topic": "Paper 1 · physical chemistry",
    "prompt": "What is the correct sequence for processes occurring in a mass spectrometer?",
    "options": [
      [
        "ppl-kenya-ppb-s1p1-015-option-0",
        "Vaporization, ionization, acceleration, deflection"
      ],
      [
        "ppl-kenya-ppb-s1p1-015-option-1",
        "Vaporization, acceleration, ionization, deflection"
      ],
      [
        "ppl-kenya-ppb-s1p1-015-option-2",
        "Ionization, vaporization, acceleration, deflection"
      ],
      [
        "ppl-kenya-ppb-s1p1-015-option-3",
        "Ionization, vaporization, deflection, acceleration"
      ]
    ],
    "answer": "ppl-kenya-ppb-s1p1-015-option-0",
    "explanation": "Vaporization is a crucial initial step in the mass spectrometry process. Before a sample can be ionized and analyzed, it must be in the gas phase.Ionization: The sample is introduced into the ionization chamber, where it is bombarded with high-energy electrons. This process knocks electrons off the sample molecules, forming positively charged ions. Acceleration: The positively charged ions are accelerated towards a detector using an electric field. This acceleration gives the ions kinetic energy. Deflection: The ions are deflected by a magnetic field. The degree of deflection depends on the mass-to-charge ratio of the ions. Lighter ions are deflected more than heavier ions. Detection: The deflected ions strike a detector, which measures the abundance of ions with different mass-to-charge ratios. This information is used to generate a mass spectrum, which is a plot of ion abundance versus m/z ratio.",
    "rationales": {},
    "source": "PharmaProLearn",
    "sourceUrl": "https://pharmaprolearn.com/exam/boards/kenya-ppb/guides/practice-questions/",
    "paper": "paper-1",
